#include <stdio.h>

/* 两两比一比、慢慢往上冒：把 a 里 n 只排成从小到大，答「一共比了几次」 */
int bubble(int a[], int n) {
    int times = 0;

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            times++;
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }

    return times;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    int a[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1;
        }
    }

    int times = bubble(a, n);

    printf("排排坐：");
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    printf("两两比一比：%d 次\n", times);
    return 0;
}
